def find_xdsl_file(filename: str = DEFAULT_XDSL_FILENAME, start_dir: Path | None = None) -> Path:
    """Find the XDSL file by walking upward from the generated module location."""
    start_path = start_dir or Path(__file__).resolve().parent
    if start_path.is_file():
        start_path = start_path.parent
    for current_dir in (start_path, *start_path.parents):
        candidate = current_dir / filename
        if candidate.exists():
            return candidate
    raise FileNotFoundError(f"Could not find XDSL file {filename!r} starting from {start_path!s}")

