class BayesianBeliefNetwork(BaseBayesianBeliefNetwork):
    """Generated pySMILE network wrapper with node-id helpers."""

    def __init__(self, xdsl_path: Optional[str] = None) -> None:
        self.network = pysmile.Network()
        source_path = Path(xdsl_path) if xdsl_path is not None else find_xdsl_file()
        if not source_path.is_absolute():
            source_path = find_xdsl_file(source_path.name, source_path.parent)
        self.network.read_file(str(source_path))
        self.network.update_beliefs()

    def clear_all_evidence(self) -> None:
        self.network.clear_all_evidence()

    def update_beliefs(self) -> None:
        self.network.update_beliefs()

    def set_evidence(self, node_id: str, state: str | int | Enum | None) -> None:
        if state is None:
            return
        if isinstance(state, Enum):
            state = state.value
        if isinstance(state, int):
            self.network.set_evidence(node_id, state)
            return

        state_index = self.get_state_index(node_id, state)
        self.network.set_evidence(node_id, state_index)

    def set_virtual_evidence(
        self, node_id: str, distribution: Mapping[str | int | Enum, float] | Sequence[float] | None
    ) -> None:
        """Set virtual (soft) evidence on a node.

        ``distribution`` is either a full likelihood vector in outcome order, or a
        mapping from state (id, index or Enum member) to likelihood; states omitted
        from a mapping get 0.0. SMILE normalizes the vector internally, so values
        need not sum to 1. ``None`` is a no-op, mirroring ``set_evidence``.
        """
        if distribution is None:
            return
        handle = self.network.get_node(node_id)
        outcome_count = self.network.get_outcome_count(handle)
        if isinstance(distribution, Mapping):
            vector = [0.0] * outcome_count
            for state, likelihood in distribution.items():
                if isinstance(state, Enum):
                    state = state.value
                index = state if isinstance(state, int) else self.get_state_index(node_id, state)
                if not 0 <= index < outcome_count:
                    raise ValueError(f"State index {index} out of range for node {node_id!r}")
                vector[index] = float(likelihood)
        else:
            vector = [float(value) for value in distribution]
            if len(vector) != outcome_count:
                raise ValueError(f"Expected {outcome_count} likelihoods for node {node_id!r}, got {len(vector)}")
        if any(value < 0.0 for value in vector) or sum(vector) <= 0.0:
            raise ValueError(f"Virtual evidence for node {node_id!r} must be non-negative with a positive sum")
        self.network.set_virtual_evidence(node_id, vector)

    def get_virtual_evidence(self, node_id: str) -> list[float]:
        return list(self.network.get_virtual_evidence(node_id))

    def is_virtual_evidence(self, node_id: str) -> bool:
        return bool(self.network.is_virtual_evidence(node_id))

    def clear_evidence(self, node_id: str) -> None:
        self.network.clear_evidence(node_id)

    def get_state_index(self, node_id: str, state_id: str) -> int:
        handle = self.network.get_node(node_id)
        for index in range(self.network.get_outcome_count(handle)):
            if self.network.get_outcome_id(handle, index) == state_id:
                return index
        raise ValueError(f"Unknown state {state_id!r} for node {node_id!r}")

    def get_node_value(self, node_id: str) -> list[float]:
        return list(self.network.get_node_value(node_id))

    def inference(self, node_id: str) -> list[float]:
        self.update_beliefs()
        return self.get_node_value(node_id)

    def snapshot(self) -> dict[str, dict]:
        """Return a snapshot of all nodes with their values and state names."""
        snapshot_data = {}
        for attr_name, node_id in vars(NodeIds).items():
            if not attr_name.isupper() or not isinstance(node_id, str):
                continue
            handle = self.network.get_node(node_id)
            if handle < 0:
                continue
            outcome_count = self.network.get_outcome_count(handle)
            states = [self.network.get_outcome_id(handle, i)
                     for i in range(outcome_count)]
            snapshot_data[node_id] = {
                'values': self.get_node_value(node_id),
                'states': states
            }
        return snapshot_data

